  "cue": "wait_for_me_backward_palm",
  "description": "Robot turns its head over its shoulder and pulses its hand backward, as if asking someone behind it to wait.",
  "movements": [
    {
      "type": "pose",
      "duration": 0.6,
      "parameters": {
        "pose": {
          "torso_height": "mid",
          "arm_position": "back",
          "gripper_orientation": "horizontal",
          "head": "right",
          "left_arm": "still",
          "elbow_bended": true,
          "z": 70
        }
      }
    },
    {
      "type": "path",
      "duration": 1.2,
      "parameters": {
        "path": {
          "mode": "ee",
          "shape": "line",
          "axis": "x",
          "distance": -0.07,
          "speed": 1.8,
          "repetition": 2,
          "hold_time": 0.1
        }
      }
    }
  ]
}
